def subtract(a, b):
    # Filter out empty intervals and sort
    a_intervals = sorted([interval for interval in a if interval[0] < interval[1]])
    b_intervals = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a_intervals:
        return []

    # Merge overlapping/touching intervals in b
    merged_b = []
    for start, end in b_intervals:
        if merged_b and start <= merged_b[-1][1]:
            merged_b[-1][1] = max(merged_b[-1][1], end)
        else:
            merged_b.append([start, end])

    # For each interval in a, subtract all intervals in merged_b
    result = []

    for a_start, a_end in a_intervals:
        # Track the current segment of a that hasn't been subtracted
        current_segments = [[a_start, a_end]]

        for b_start, b_end in merged_b:
            new_segments = []
            for seg_start, seg_end in current_segments:
                # No overlap
                if seg_end <= b_start or seg_start >= b_end:
                    new_segments.append([seg_start, seg_end])
                else:
                    # There is overlap
                    # Keep the part before b_start
                    if seg_start < b_start:
                        new_segments.append([seg_start, b_start])
                    # Keep the part after b_end
                    if seg_end > b_end:
                        new_segments.append([b_end, seg_end])
            current_segments = new_segments

        result.extend(current_segments)

    # Merge adjacent/overlapping intervals in result
    if not result:
        return []

    result.sort()
    merged_result = []
    for start, end in result:
        if merged_result and start <= merged_result[-1][1]:
            merged_result[-1][1] = max(merged_result[-1][1], end)
        else:
            merged_result.append([start, end])

    return merged_result

